int reco()
{
  // Macro created 20/09/2006 by S.Spataro
  // It loads a digi file and performs tracking

  // Verbosity level (0=quiet, 1=event level, 2=track level, 3=debug)
  Int_t iVerbose = 0; // just forget about it, for the moment
  
	// Number of events to process
  Int_t nEvents = 0;  // if 0 all the vents will be processed
  
  TString simFile = "sim.root";
  PndFileNameCreator creator(simFile.Data());
  TString digiFile = creator.GetDigiFileName();
  TString recoFile = creator.GetRecoFileName();
  TString parFile = creator.GetParFileName();
  
  // Digitisation file (ascii)
  TString digiParFile = "all.par";
  
  // -----   Timer   --------------------------------------------------------
  TStopwatch timer;
    // ------------------------------------------------------------------------
  
  // -----   Reconstruction run   -------------------------------------------
  FairRunAna *fRun= new FairRunAna();
  fRun->SetInputFile(simFile);
  fRun->AddFriend(digiFile);
  fRun->SetOutputFile(recoFile);
  fRun->SetGenerateRunInfo(kFALSE);
  FairGeane *Geane = new FairGeane();
  fRun->AddTask(Geane);

  // -----  Parameter database   --------------------------------------------
  TString emcDigiFile = gSystem->Getenv("VMCWORKDIR");
  emcDigiFile += "/macro/params/";
  emcDigiFile += digiParFile;
  
  FairRuntimeDb* rtdb = fRun->GetRuntimeDb();
  FairParRootFileIo* parInput1 = new FairParRootFileIo();
  parInput1->open(parFile.Data());
  
  FairParAsciiFileIo* parIo1 = new FairParAsciiFileIo();
  parIo1->open(emcDigiFile.Data(),"in");
        
  rtdb->setFirstInput(parInput1);
  rtdb->setSecondInput(parIo1);

  // ------------------------------------------------------------------------

  // -----   MDV hit producers   ---------------------------------
  PndMvdClusterTask* mvdmccls = new PndMvdClusterTask();
  mvdmccls->SetVerbose(iVerbose);
  fRun->AddTask(mvdmccls);
  // -----   STT digi producers   ---------------------------------
  PndSttHitProducerRealFast* sttHitProducer = new PndSttHitProducerRealFast();
  fRun->AddTask(sttHitProducer);
  // -----   EMC hit producers   ---------------------------------
  PndEmcMakeCluster* emcMakeCluster= new PndEmcMakeCluster(iVerbose);
  fRun->AddTask(emcMakeCluster);
  
  PndEmcMakeBump* emcMakeBump= new PndEmcMakeBump();
  fRun->AddTask(emcMakeBump);
  // -----   SciT hit producers   ---------------------------
  PndSciTHitProducerIdeal* tofhit = new PndSciTHitProducerIdeal();
  tofhit->SetVerbose(iVerbose);
  fRun->AddTask(tofhit);

  // -----   MDT hit producers   ---------------------------------
  PndMdtHitProducerIdeal* mdtHitProd = new PndMdtHitProducerIdeal();
  mdtHitProd->SetPositionSmearing(.3); // position smearing [cm]
  fRun->AddTask(mdtHitProd);
  
  PndMdtTrkProducer* mdtTrkProd = new PndMdtTrkProducer();
  fRun->AddTask(mdtTrkProd);

  // -----   DRC hit producers   ---------------------------------
  PndDrcHitProducerReal* drchit = new PndDrcHitProducerReal();
  drchit->SetVerbose(iVerbose);
  fRun->AddTask(drchit);

  // -----   GEM hit producers   ---------------------------------
  PndGemFindHits* gemFindHits = new PndGemFindHits("GEM Hit Finder", iVerbose);
  fRun->AddTask(gemFindHits);
  // -----   FTS hit producers   ---------------------------------
  PndFtsHitProducerRealFast* ftsHitProducer = new PndFtsHitProducerRealFast();
  fRun->AddTask(ftsHitProducer);

  // -----   Ftof hit producers   ---------------------------
  PndFtofHitProducerIdeal* ftofhit = new PndFtofHitProducerIdeal();
  ftofhit->SetVerbose(iVerbose);
  fRun->AddTask(ftofhit);

object.09e0d0e722de413b72e39fc7.text:
void PndRhoTupleQA::qaComp(TString pre, RhoCandidate *c, RhoTuple *n, bool covs, bool pulls)
{
  if (n==0) return;

  // what kind of particle?
  //int pdg = c->PdgCode(); //[R.K. 01/2017] unused variable

  // special composite particle?
  // pi0 or eta?
  //if (pdg == 111 || pdg == 221)
  //{
    //qaPi0(pre, c, n);
    //return;
  //}
  //// K_S?
  //if (pdg == 310)
  //{
    //qaKs0(pre, c, n);
    //return;
  //}

  // how many daughters?
  int nd = c->NDaughters();

  // truth match already done?
  RhoCandidate *truth = c->GetMcTruth();

  // if not, try one
  if (truth == 0 && fAnalysis != 0)
  {
    fAnalysis->McTruthMatch(c);
    truth = c->GetMcTruth();
  }

  bool mct = false;
  if (truth!=0)
  {
    if (nd>0) mct = true;
    else mct = (truth->PdgCode()==c->PdgCode());
  }
  // store cand info in lab and cms
  qaCand(pre,  c,  n);
  qaP4Cms(pre, c->P4(), n);
  if(covs)qaP4Cov(pre,  c,  n);
  if(pulls) qaPull(pre,c,n, (0==truth));
  n->Column(pre+"mct",  (Float_t) mct, 0.0f);

  // for mass difference e.g. D* -> D pi decays
  if (nd>=2) n->Column(pre+"mdif", (Float_t) (c->M() - c->Daughter(0)->M()), 0.0f);

  // cand is final state particle
  if (nd==0)
  {
    // charged particle -> store PID info
    if ( fabs(c->Charge())>0.1 ) qaPid(pre,  c,  n);

    // and pdg code from truth
    Float_t trpdg = 0.;
    if (truth) trpdg = truth->PdgCode();
    n->Column(pre+"trpdg", (Float_t) trpdg, 0.0f);
  }
  // cand is composite
  else
  {
    // if 2 daughters -> store decay angle etc
    if (nd==2) qa2Body(pre, c, n);
    // if 3 daughters -> dalitz plot vars
    if (nd==3) qaDalitz(pre, c, n);

    // counter for charged final states
    int nchrgfs = 0;

    for (int i=0; i<nd; ++i)
    {
      RhoCandidate *dau = c->Daughter(i);
      TString name=TString::Format("%sd%d",pre.Data(),i);

      // count charged final states for possible vertexing later
      if (dau->NDaughters()==0 && fabs(dau->Charge())>0.01) nchrgfs++;

      // recursive call of qaComp
      qaComp(name, dau, n, covs, pulls);
    }
    // only charged final state daughters -> Vtx info with RhoVtxPoca
    if (nchrgfs > 1)
    {
      qaPoca(pre, c, n);
      qaVtx(pre, c, n);
    }
  }
}

object.0b2c13ac19e319aac0be7079.text:
void PndRhoTupleQA::qaKs0(TString pre, RhoCandidate *c, RhoTuple *n)
{
  if (n==0) return;

  RhoCandidate *d0 = c->Daughter(0);
  RhoCandidate *d1 = c->Daughter(1);
  double ang = d0->P3().Angle(d1->P3());

  if (fAnalysis!=0) fAnalysis->McTruthMatch(c);
  RhoCandidate *truth = c->GetMcTruth();

  qaCand(pre, c, n);
  qaPoca(pre, c, n);
  qaVtx(pre, c, n);

  n->Column(pre+"oang",(Float_t) ang,    0.0f);

  qaCand(pre+"d0", d0, n);
  qaPid(pre+"d0",  d0, n);

  qaCand(pre+"d1", d1, n);
  qaPid(pre+"d1",  d1, n);

  if (truth!=0)
  {
    TVector3 vdist = truth->Pos() - truth->Daughter(0)->Pos();
    Float_t dist = vdist.Mag();
    Float_t ctau = dist * truth->M() / truth->P();

    qaCand("t"+pre, truth, n);
    n->Column(pre+"mct", 1.0f, 0.0f);
    n->Column("t"+pre+"dist",    (Float_t) dist , 0.0f);
    n->Column("t"+pre+"ctau", (Float_t) ctau , 0.0f);
  }
  else
  {
    qaCand("t"+pre, NULL , n, true);
    n->Column(pre+"mct", 0.0f, 0.0f);
    n->Column("t"+pre+"dist", (Float_t) -999. , 0.0f);
    n->Column("t"+pre+"ctau", (Float_t) -999. , 0.0f);
  }
}

object.130d7834a6fe03a7867adee1.text:
Double_t RhoVtxPoca::GetPocaTwoCharged(TVector3& vertex,RhoCandidate* a, RhoCandidate* b)
{
  // Calculate an approximate POCA for two helices.
  // First in 2D (x-y projection), then select best solution by minimum z distance
  
  vertex.SetXYZ(0.,0.,0.);
  Double_t bField = 0.1*RhoCalculationTools::GetBz(vertex); // T, assume field in z only
  Double_t bc = 0.0029979246*bField;
  TVector3 dB(0,0,1.0);
  TVector3 position1 = a->GetPosition();
  // Momentum vectors
  TVector3 ap3 = a->P3();
  Double_t pPerp1 = ap3.Perp();
  TVector3 d1 = ap3;
  d1.SetZ(0);
  d1*=1.0/pPerp1;

  // Radius and center
  Double_t rho1 = pPerp1/bc; // Radius in cm
  TVector3 r1=d1.Cross(dB);
  r1 *= -a->Charge()*rho1;
  TVector3 center1 = position1 - r1;
  center1.SetZ(0);

  TVector3 position2 = b->GetPosition();

  // Momentum vectors
  TVector3 bp3 = b->P3();
  Double_t pPerp2 = bp3.Perp();
  TVector3 d2 = bp3;
  d2.SetZ(0);
  d2*=1.0/pPerp2;

  // Radius and center
  Double_t rho2 =  pPerp2/bc; // Radius in cm
  TVector3 r2=d2.Cross(dB);
  r2 *= -b->Charge()*rho2;
  TVector3 center2 = position2 - r2;
  center2.SetZ(0);

  // distance and angle of the axis between the two centers
  TVector3 ab = center2 - center1;
  Double_t dab = ab.Perp();
  Double_t cosTheAB = ab.X()/dab;
  Double_t sinTheAB = ab.Y()/dab;

  Double_t darr = dab;
  darr -= rho1;
  darr -= rho2;

  // both circles do not intersect (only one solution)
  Int_t nSolMax=1;
  Double_t x=0;
  Double_t y=0;
  if (darr < 0) {
    // sum of radii is smaller than the two centers distance, circles intersect at two points
    nSolMax=2;
    // x value of intersect at reduced system
    x = 0.5*dab + ( rho1*rho1 - rho2*rho2 )/(2*dab);
    // y*y value of intersect at reduced system for helix A
    Double_t y2 = (rho1+x)*(rho1-x);
    if (y2 > 0) { y = sqrt(y2); }
  } else {
    // no intersecting circles, take the mid point between both circles
    x = 0.5*(dab + rho1 - rho2);
  }
  // now we compute the solution(s)
  TVector3 newapos[2];
  TVector3 newbpos[2];
  Int_t best=0;
  Double_t actualDoca=1.E8;
  for (Int_t ns=0; ns<nSolMax; ns++) {     // loop on the solutions
    // radius vector of intersection point
    Double_t sign = ns ? 1.0 : -1.0;
    TVector3 rs1( cosTheAB*x - sinTheAB*y * sign, sinTheAB*x + cosTheAB*y * sign, 0);
    TVector3 rs2( rs1-ab );

    // are we moving forward or backward?
    Double_t adir=(rs1-r1).Dot(ap3)>0 ? 1.0 : -1.0;
    Double_t aangle=adir * r1.Angle(rs1);
    // intersection point
    Double_t newaz=position1.Z() + rho1*aangle/pPerp1 * ap3.Z();
    newapos[ns].SetX( center1.X() + rs1.X() );
    newapos[ns].SetY( center1.Y() + rs1.Y() );
    newapos[ns].SetZ( newaz );

    // same for b
    Double_t bdir=(rs2-r2).Dot(bp3)>0 ? 1.0 : -1.0;
    Double_t bangle=bdir * r2.Angle(rs2);
    Double_t newbz=position2.Z() + rho2*bangle/pPerp2 * bp3.Z();
    newbpos[ns].SetX( center2.X() + rs2.X());   // ==newapos[ns].X()
    newbpos[ns].SetY( center2.Y() + rs2.Y());   // ==newapos[ns].Y()
    newbpos[ns].SetZ( newbz );

    Double_t delta = (newapos[ns]-newbpos[ns]).Mag();

    // take the solution of minimal deltaZ
    if ( delta < actualDoca ) {
      best=ns;
      actualDoca  = delta;
    }
  }
  vertex=0.5*(newapos[best]+newbpos[best]);
  return actualDoca;
}

object.25bfb752235ce4c8c1672151.text:
Double_t RhoVtxPoca::GetPocaTwoNeutral(TVector3& vertex,RhoCandidate* canda, RhoCandidate* candb)
 {
   // This is the exact(!) skewed line POCA
   //
   
   vertex.SetXYZ(0.,0.,0.);
   
   TVector3 av = canda->GetPosition();
   TVector3 ap = canda->P3();
   
   TVector3 bv = candb->GetPosition();
   TVector3 bp = candb->P3();
   
   TVector3   u = ap.Unit();
   TVector3   v = bp.Unit();
   TVector3   w = av - bv;
   double     a = u.Mag(); //dot(u,u);         // always >= 0
   double     b = u.Dot(v); //dot(u,v);
   double     c = v.Mag(); //dot(v,v);         // always >= 0
   double     d = u.Dot(w); //dot(u,w);
   double     e = v.Dot(w); //dot(v,w);
   double     D = a*c - b*b;        // always >= 0
   double     sc, tc;
   
   // compute the line parameters of the two closest points
   if (D < 1e-9) {          // the lines are almost parallel
     sc = 0.0;
     tc = (b>c ? d/b : e/c);    // use the largest denominator
   }
   else {
       sc = (b*e - c*d) / D; //determination of s in g: x1 = av + s*ap
       tc = (a*e - b*d) / D; //determination of t in h: x2 = bv + t*bp
       	  	  	  	  	  	//using (x1-x2)*u = 0 and (x1-x2)*v = 0
   }
   
   // get the difference of the two closest points
   //TVector3   dP = w + (sc * u) - (tc * v);  // =  L1(sc) - L2(tc)
   TVector3   pocaa = av + sc*u;
   TVector3   pocab = bv + tc*v;
   vertex = 0.5*(pocaa+pocab);
   TVector3   diff = pocaa-pocab;
   
   return diff.Mag();   // return the closest distance
   
 }

object.489090704a30da9039b50aac.text:
Int_t RhoCandList::RemoveFamily ( RhoCandidate* c )
{
  Int_t nRemoved = 0;
  Int_t n = GetNumberOfTracks();
  for ( Int_t i=0; i<n; i++ ) {
    RhoCandidate* b = Get ( i );
    if ( b->Overlaps ( c ) ) {
      fOwnList->RemoveAt ( i );
      nRemoved++;
    }
  }
  fOwnList->Compress();
  return nRemoved;
}

object.59f6da2f9030a2a0e09d6e1b.text:
#include "selectEvents.h"

using namespace std;

void selectEvents(int pdg,
		  const std::string& partName,
		  const std::string& paramFile  ,
		  const std::string& simFile    ,
		  const std::string& digiFile   ,
		  const std::string& recoFile   ,
		  const std::string& outFileName
		  )
{
  int counts = 0;
  TStopwatch timer;
  timer.Start();

  cout << "\tCount = " << counts
       << "\n\tpdg = " << pdg << '\n';

  // First = event id. Second = MC_moment
  std::vector < std::pair<int, float> > EvtIds;

  // EMC cluster energy, num.clusters, numb. crystals
  float emc, emcOld, mom, MCmom;

  // Selected Zernike moments and LATeral energydeposition
  float z20, z53, latEdep;

  int numClus, numCrys, numBumps;

  // Selected cluster properties.
  float E1, E9, E25, E1E9, E9E25;

  MCmom = mom = emc = emcOld = z20 = z53 = 0.0;
  E1 = E9 = E25 = E1E9 = E9E25 = 0.0;
  numClus = numCrys = numBumps = 0;

  // N-Tuple to store the variables.
  TNtuple EmcNtp (partName.c_str(), partName.c_str(),
		  "MCp:p:emc:emcOld:lat:z20:z53:numClus:numCrys:numBumps:E1:E9:E25:E1E9:E9E25");

  // Open Simulation file
  TFile sF(simFile.c_str());

  // Get simulation tree
  TTree* tsim = (TTree *) sF.Get("pndsim");

  // Tracks.
  TClonesArray* trackList = new TClonesArray("PndMCTrack");
  tsim->SetBranchAddress("MCTrack", &trackList);

  // Points
  TClonesArray* pointList = new TClonesArray("PndEmcPoint");
  tsim->SetBranchAddress("EmcPoint", &pointList);

  // Maybe it can be done better (Cleaner).
  ////////////////////////////
  FairRunAna *fRun= new FairRunAna();
  fRun->SetInputFile(simFile.c_str());

  // Dummy output, containes nothing
  fRun->SetOutputFile("dummy_out.root");

  FairRuntimeDb* rtdb = fRun->GetRuntimeDb();
  FairParRootFileIo* parInput1 = new FairParRootFileIo();

  parInput1->open(paramFile.c_str());
  rtdb->setFirstInput(parInput1);

  PndEmcGeoPar *geoPar = (PndEmcGeoPar*) rtdb->getContainer("PndEmcGeoPar");
  fRun->Init();

  geoPar->InitEmcMapper();

  PndEmcMapper::Init(1);

  ////////////////////////////

  // Open Digi file
  TFile digiF(digiFile.c_str());

  // Digi tree
  TTree* digiTr = (TTree *) digiF.Get("pndsim");

  // Digi Array
  TClonesArray* digi_arr = new TClonesArray("PndEmcDigi");
  digiTr->SetBranchAddress("EmcDigi", &digi_arr);

  // CLusters Array
  TClonesArray* clusters_arr = new TClonesArray("PndEmcCluster");
  digiTr->SetBranchAddress("EmcCluster", &clusters_arr);

  // Bumps Array
  // TClonesArray* bumps_arr = new TClonesArray("PndEmcBump");
  // digiTr->SetBranchAddress("EmcBump", &bumps_arr);

  // Open Reco file
  TFile recoF(recoFile.c_str());

  // Reco tree
  TTree* RecoTr = (TTree *) recoF.Get("pndsim");

  // Track list
  TClonesArray* recTrakArr = new TClonesArray("PndTrack");
  RecoTr->SetBranchAddress("SttMvdGemGenTrack", &recTrakArr);

  // Loop through the simulation data.
  std::cout << "<INFO> Selecting events." << '\n';

  for (int j = 0; j < tsim->GetEntriesFast(); j++)
  {
    tsim->GetEntry(j);

    // Select the first interaction point.
    PndEmcPoint* pt   = (PndEmcPoint*) pointList->At(0);

    if(pt)
    {
      int trID = pt->GetTrackID();
      PndMCTrack* track = (PndMCTrack*) trackList->At(trID);

      // Select events with the correct pdg code.
      if( track->GetPdgCode() == pdg )
      {
        counts++;
	// First = event Index, Second = MC Moment
	EvtIds.push_back( std::make_pair(j, (track->GetMomentum()).Mag()) );
      }
      else{ // Decay ????
        std::cout << "<Wrong pdg> :"
		  << " Track ID = " << trID
		  << " Track has pdg = " << track->GetPdgCode()
		  << '\n';
      }
    }
    else
    {// No emc interaction??
      std::cout << "No point on the EMC.\n";
    }
  }

  std::cout << "<INFO> Processing selected events.\n";

  // Loop through the selected events.
  for(size_t i = 0; i < EvtIds.size(); i++)
  {
    mom = MCmom = -1.00;
    // Event index
    int evid = EvtIds[i].first;

    cout << "Selected Event no = " << evid << " ";

    tsim->GetEntry(evid);
    digiTr->GetEntry(evid);
    RecoTr->GetEntry(evid);

    // Track for the primary particle. Other indices correspond to
    // secondary ....
    PndTrack* tra = (PndTrack*) recTrakArr->At(0);

    if(tra)
    {
      // Charged or correct reconstructed.
      FairTrackParP par = tra->GetParamLast();

      mom = par.GetMomentum().Mag();// Computed (Reco.) moment
      MCmom = EvtIds[i].second;// MC moment

      std::cout << "Number of clusters = "
		<< clusters_arr->GetEntriesFast()
		<<" Number of tracks = "<< recTrakArr->GetEntriesFast()
		<< " With p = "<< mom
		<< " MC_p = "  << MCmom
		<< '\n';

      // Select the right cluster(highest E_dep).
      double maxEnergy = std::numeric_limits <double>::min();
      int clIndex      = -1;

      // Loop through the clusters.
      for(int cl = 0; cl < clusters_arr->GetEntriesFast(); cl++)
      {
	PndEmcCluster* clust = (PndEmcCluster*) clusters_arr->At(cl);

	if(clust->GetEnergyCorrected() > maxEnergy)
	{
	  maxEnergy = clust->GetEnergyCorrected();
	  clIndex = cl;
	}
      }

      // Found the cluster with highest E_dep.
      if( clIndex >= 0 )
      {
	PndEmcCluster* HE_cluster = (PndEmcCluster*) clusters_arr->At(clIndex);

	std::cout << " Number of involved digis = " << digi_arr->GetEntries()
		  << '\n';

	PndEmcClusterEnergySums Som ( (*HE_cluster), digi_arr);

	emcOld   = HE_cluster->energy();
	emc      = HE_cluster->GetEnergyCorrected();

	numClus  = clusters_arr->GetEntriesFast();
	numCrys  = HE_cluster->NumberOfDigis();
	numBumps = HE_cluster->NBumps();

	// Z_{n = 2}^{m = 0}
	z20 = HE_cluster->Z20();

	// Z_{n = 5}^{m = 3}
	z53 = HE_cluster->Z53();

	//lat Edep
	latEdep = HE_cluster->LatMom();

	E1    = Som.E1();
	E9    = Som.E9();
	E25   = Som.E25();
	E1E9  = Som.E1E9();
	E9E25 = Som.E9E25();

	// Fill tree (NTuple)
	// If something WENT wrong, during the fitting
	if( tra->GetFlag() > 0 )
	{
	  EmcNtp.Fill(MCmom, mom, emc, emcOld,
		      latEdep, z20, z53,
		      numClus, numCrys, numBumps,
		      E1, E9, E25, E1E9, E9E25);

	  std::cout << " Cluster index = "<< clIndex
		    << " emcOld = " << emcOld
		    << " emc = "    << emc
		    << " Track Flag = " << tra->GetFlag()
		    << " E1  = "    << Som.E1()
		    << " E9  = "    << Som.E9()
		    << " E25 = "    << Som.E25()
		    << " E1E9 = "   << Som.E1E9()
		    << " E9E25 = "  << Som.E9E25()
		    << '\n';
	}// IF(tra->GetFlag() > 0)
      }// IF(clIndex >= 0)
    }// End if(tra)
    else
    {//Neutral or not correctly reconstructed.
      cout << "<Empty track>: number of clusters = "
	   << clusters_arr->GetEntriesFast() << '\n';
    }
  }//Selected Event loop

  std::cout << "========================================================\n"
	    << "<INFO>\nTotal number of events = " << tsim->GetEntriesFast()
	    << "\nPdg = " << pdg << " Particle = " << partName
            << "\nNo decay = " << counts
            << "\nNo decay array size = " << EvtIds.size()
	    << "\nIn Ntuple " << EmcNtp.GetEntriesFast()
	    << "\nNumber of events in reco file = " << RecoTr->GetEntriesFast()
	    << "\n========================================================\n";

  std::cout << "<INFO> Writing output to: " << outFileName << '\n';

  // Write to the output
  TFile out(outFileName.c_str(), "RECREATE","Selected evets File.", 9);

  EmcNtp.Write();

  out.Close();

  //=========== Clean-up
  EvtIds.clear();
  sF.Close();
  digiF.Close();
  recoF.Close();

  delete clusters_arr;
  delete trackList;
  delete pointList;
  delete recTrakArr;

  timer.Stop();

  Double_t rtime = timer.RealTime();
  Double_t ctime = timer.CpuTime();
  cout <<"=======================================\n"
       << "Macro finished succesfully.\n"
       << "Real time " << rtime << " s, CPU time " << ctime << " s.\n\n";
  // ------------------------------------------------------------------------
  exit(0);
}

object.5b7dc0cbd9a326e0c66eb976.text:
Double_t RhoVtxPoca::GetPocaVtx(TVector3& vertex, RhoCandList  &cands)
{
	vertex.SetXYZ(0.,0.,0.);
	if ( cands.GetLength() <  2 ) { return -99999.; }
	if ( cands.GetLength() == 2 ) { return GetPoca(vertex, cands[0], cands[1]); }

	std::vector<Double_t> distances;
	std::vector<TVector3> results;
	// loop over daughters, take the mean value of all "best" positions
	// TODO do this smarter by using already found vertices ?
	TVector3 theVertex(0.,0.,0.);
	Double_t actualDoca=0.;
	
	for(Int_t daug1 =0; daug1<cands.GetLength(); daug1++) 
	{
		RhoCandidate* a=cands[daug1];
		
		for(Int_t daug2=daug1+1; daug2<cands.GetLength(); daug2++) 
		{
			RhoCandidate* b=cands[daug2];
			
			actualDoca = GetPoca(theVertex,a,b);
			if(actualDoca < 0) 
			{
				printf("RhoVtxPoca - Error with getting a POCA. \"Distance\" is %g. SKIPPING Candidate pair now!",actualDoca);
				continue;
			}
			distances.push_back(actualDoca);
			results.push_back(theVertex);
		}//daug2
	}//daug1
	
	// Averaging vertex results from each track pair, weighted with 1/distance
	std::vector<Double_t>::iterator iterDoca;
	std::vector<TVector3>::iterator iterVtx;
	Double_t docaweight=0,sumdocaweigts=0;
	TVector3 vertexK;
	for(iterVtx=results.begin(), iterDoca=distances.begin(); iterVtx!=results.end()&&iterDoca!=distances.end(); ++iterVtx,++iterDoca) 
	{
		docaweight=1/(*iterDoca);
		//docaweight *= docaweight;
		vertexK=*iterVtx;
		if (docaweight == 0) { docaweight = 1; } // right so?
		vertexK *= docaweight;
		vertex+=vertexK;
		sumdocaweigts+=docaweight;
	}
	if (sumdocaweigts == 0) { sumdocaweigts=1; }
	vertex*=1./sumdocaweigts;
	//sumdocaweigts = sqrt(sumdocaweigts);
	return cands.GetLength()/sumdocaweigts;
		
}

