InitStatus PndPidCorrelator::Init()
{
  if (fTrackingSystemInfo == nullptr && fCalorimeterInfo == nullptr) {
    LOG(error) << "PndPidCorrelator(" << GetName() << ")::Init(): Neither tracking nor calorimeter info set, abort!";
    return kFATAL;
  }
  if (fIdealHyp && fTrackingSystemInfo != nullptr) {
    if (!fTrackingSystemInfo->SetMcTrack(fManager)) {
      return kERROR;
    }
  } else {
    fPidHyp = FindPidHyp(fPidHyp);
  }

  if (fIdeal) {
    LOG_IF(info, fVerbose > 0) << "PndPidCorrelator::Init: Using MonteCarlo correlation";
  }

  Register();

  fCorrPar->printParams();

  if (fUsePropagator) {
    SetPropagator(fPropagator);
    if (fTrackingSystemInfo != nullptr) {
      fTrackingSystemInfo->SetPropagator(fPropagator);
    }
  }

  if (fDebugMode) {
    fFileDebugNtuples = TFile::Open(fDebugDir + fDebugFile, "RECREATE");
    LOG_IF(info, fVerbose > 8) << "PndPidCorrelator::Init: Filling Debug histograms";
  }

  SetupDetectorParams();
  if (fTrackingSystemInfo != nullptr) {
    if (!fTrackingSystemInfo->Setup(fManager, fPropagator, &fDetectorParams)) {
      return kFATAL;
    }
  } else {
    LOG_IF(info, fVerbose > 0) << "PndPidCorrelator::Init(): No tracking information -> create only neutral candidates";
  }

  if (fCalorimeterInfo != nullptr) {
    if (!fCalorimeterInfo->Setup(fManager, fPropagator, &fDetectorParams)) {
      return kFATAL;
    }
  } else {
    LOG_IF(info, fVerbose > 0) << "PndPidCorrelator::Init(): No calorimeter information -> create only charged candidates";
  }

  for (Int_t i = fBarrelDetectors.size() - 1; i >= 0; i--) {
    if (fBarrelDetectors.at(i) == nullptr) {
      LOG(warn) << "PndPidCorrelator::Init: Barrel detector " << i << " is not set!";
      LOG_IF(info, fVerbose > 5) << "Removing it from fBarrelDetectors.";
      fBarrelDetectors.erase(fBarrelDetectors.begin() + i);
      continue;
    }
    if (!(fBarrelDetectors.at(i))->Setup(fManager, fPropagator, &fDetectorParams)) {
      return kFATAL;
    }
  }
  for (Int_t i = fForwardDetectors.size() - 1; i >= 0; i--) {
    if (fForwardDetectors.at(i) == nullptr) {
      LOG(warn) << "PndPidCorrelator::Init: Forward detector " << i << " is not set!";
      LOG_IF(info, fVerbose > 5) << "Removing it from fForwardDetectors.";
      fForwardDetectors.erase(fForwardDetectors.begin() + i);
      continue;
    }
    if (!(fForwardDetectors.at(i))->Setup(fManager, fPropagator, &fDetectorParams)) {
      return kFATAL;
    }
  }

  if (fFast) {
    LOG_IF(info, fVerbose > 0) << "PndPidCorrelator::Init: Using fast correlator!!";
  }

  LOG_IF(info, fVerbose > 5) << "PndPidCorrelator::Init: Success!";
  fEventCounter = 0;
  return kSUCCESS;
}

